import { store } from './lib/store';

type Item = { id: string; text: string; done: boolean };

const KEY = 'items';

const app = document.querySelector<HTMLElement>('#app');
if (!app) throw new Error('#app not found');

let items: Item[] = [];

function render(): void {
  const done = items.filter((i) => i.done).length;
  app!.innerHTML = `
    <h1>Quiet Harbor</h1>
    <p>A vanilla TypeScript + Vite PWA. Works offline, installs on Windows and Android.</p>

    <div class="card">
      <div class="row" style="justify-content: space-between; align-items: center;">
        <strong>${done}/${items.length} done</strong>
        <span class="pill" id="status">checking…</span>
      </div>
      <ul id="list">${items.map(row).join('')}</ul>
      <form class="row" id="add">
        <input id="text" placeholder="Add an item" autocomplete="off" required />
        <button type="submit">Add</button>
      </form>
    </div>
  `;

  app!.querySelector<HTMLFormElement>('#add')!.addEventListener('submit', (event) => {
    event.preventDefault();
    const input = app!.querySelector<HTMLInputElement>('#text')!;
    const text = input.value.trim();
    if (!text) return;
    items = [...items, { id: crypto.randomUUID(), text, done: false }];
    input.value = '';
    void persist();
    render();
  });

  app!.querySelectorAll<HTMLInputElement>('[data-id]').forEach((box) => {
    box.addEventListener('change', () => {
      items = items.map((i) => (i.id === box.dataset.id ? { ...i, done: box.checked } : i));
      void persist();
      render();
    });
  });

  void showStatus();
}

function row(item: Item): string {
  return `<li><label><input type="checkbox" data-id="${item.id}" ${item.done ? 'checked' : ''} /> ${escapeHtml(item.text)}</label></li>`;
}

function escapeHtml(value: string): string {
  return value.replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[c]!);
}

async function persist(): Promise<void> {
  await store.set(KEY, items);
}

async function showStatus(): Promise<void> {
  const el = app!.querySelector<HTMLElement>('#status');
  if (!el) return;
  const online = navigator.onLine;
  const controlled = 'serviceWorker' in navigator && Boolean(navigator.serviceWorker.controller);
  el.textContent = `${online ? 'online' : 'offline'} · sw ${controlled ? 'active' : 'warming'}`;
  el.style.color = online ? 'var(--accent)' : '#f4a261';
}

async function boot(): Promise<void> {
  items = (await store.get<Item[]>(KEY)) ?? [];
  render();

  if ('serviceWorker' in navigator && import.meta.env.PROD) {
    try {
      await navigator.serviceWorker.register(new URL('./sw.js', document.baseURI), { scope: './' });
    } catch (error) {
      console.warn('service worker registration failed', error);
    }
  }

  window.addEventListener('online', () => void showStatus());
  window.addEventListener('offline', () => void showStatus());
}

void boot();
