// Offline-first key/value store.
// IndexedDB is the source of truth; localStorage mirrors small primitives so the
// UI can render synchronously on first paint. No network, no backend.

const DB_NAME = 'app-db';
const STORE = 'kv';
const MIRROR_PREFIX = 'mirror:';

function openDb(): Promise<IDBDatabase> {
  return new Promise((resolve, reject) => {
    const req = indexedDB.open(DB_NAME, 1);
    req.onupgradeneeded = () => {
      const db = req.result;
      if (!db.objectStoreNames.contains(STORE)) db.createObjectStore(STORE);
    };
    req.onsuccess = () => resolve(req.result);
    req.onerror = () => reject(req.error ?? new Error('indexedDB open failed'));
  });
}

async function tx<T>(mode: IDBTransactionMode, run: (store: IDBObjectStore) => IDBRequest<T>): Promise<T> {
  const db = await openDb();
  try {
    return await new Promise<T>((resolve, reject) => {
      const transaction = db.transaction(STORE, mode);
      const req = run(transaction.objectStore(STORE));
      req.onsuccess = () => resolve(req.result);
      req.onerror = () => reject(req.error ?? new Error('indexedDB request failed'));
    });
  } finally {
    db.close();
  }
}

export const store = {
  async get<T>(key: string): Promise<T | undefined> {
    try {
      return (await tx<T | undefined>('readonly', (s) => s.get(key) as IDBRequest<T | undefined>)) ?? undefined;
    } catch {
      const raw = localStorage.getItem(MIRROR_PREFIX + key);
      return raw === null ? undefined : (JSON.parse(raw) as T);
    }
  },

  async set<T>(key: string, value: T): Promise<void> {
    await tx<IDBValidKey>('readwrite', (s) => s.put(value, key));
    if (typeof value === 'string' || typeof value === 'number' || typeof value === 'boolean') {
      localStorage.setItem(MIRROR_PREFIX + key, JSON.stringify(value));
    }
  },

  async remove(key: string): Promise<void> {
    await tx<undefined>('readwrite', (s) => s.delete(key));
    localStorage.removeItem(MIRROR_PREFIX + key);
  },

  async keys(): Promise<string[]> {
    const all = await tx<IDBValidKey[]>('readonly', (s) => s.getAllKeys());
    return all.map(String);
  },
};
